WITH base AS (SELECT * FROM order_items WHERE product_id IS NULL AND quantity >= 6), unit_price_bucket_summary AS (SELECT CASE WHEN unit_price >= 410 THEN 'high' WHEN unit_price >= 80 THEN 'mid' ELSE 'low' END AS unit_price_bucket, MAX(unit_price) - MIN(unit_price) AS unit_price_range FROM base GROUP BY CASE WHEN unit_price >= 410 THEN 'high' WHEN unit_price >= 80 THEN 'mid' ELSE 'low' END) SELECT unit_price_bucket, unit_price_range FROM unit_price_bucket_summary WHERE unit_price_range > 72 ORDER BY unit_price_range DESC
